sql.if:
and (p.owner_user_id = #{params.projectAccessUserId}
     or exists (select 1 from review_project_member pm
                where pm.project_id = p.project_id
                  and pm.user_id = #{params.projectAccessUserId}
                  and pm.status = '0'))

mapper.select:
SELECT m.*
FROM review_member_stats_daily m
INNER JOIN review_project p ON p.project_id = m.project_id
INNER JOIN sys_business_system bs ON bs.system_id = p.business_system_id
INNER JOIN sys_dept d ON d.dept_id = p.dept_id
INNER JOIN sys_user owner ON owner.user_id = p.owner_user_id
WHERE m.stat_date >= #{params.beginDate}
  AND m.stat_date <= #{params.endDate}

    AND p.business_system_id = #{params.businessSystemId}


    AND m.project_id = #{params.projectId}


    AND m.author_key IN

        #{k}


${params.dataScope}

ORDER BY m.stat_date ASC, m.author_key ASC

SELECT m.author_key AS author_key, MAX(m.author_name) AS author_name, SUM(m.commit_count) AS commit_count, SUM(m.tasks_reviewed) AS tasks_reviewed, SUM(m.additions_sum) AS additions_sum, SUM(m.deletions_sum) AS deletions_sum, SUM(m.issues_new) AS issues_new, MAX(m.issues_open) AS issues_open FROM review_member_stats_daily m WHERE m.stat_date >= #{beginDate} AND m.stat_date <= #{endDate}
AND m.author_key IN
#{k}
AND m.project_id IN
#{pid}
GROUP BY m.author_key ORDER BY commit_count DESC

SELECT MIN(stat_date) FROM review_member_stats_daily
author_key IN
#{k}
AND project_id IN
#{pid}
AND 1 = 0
